  executor: null | ((
    env: Env,
    reviewId: string,
    maxCycles?: number,
    options?: { cochangeGithubToken?: string | null; openrouterApiKey?: string | null }
  ) => Promise<void>)
): void {
  reviewRunnerExecutorForTests = executor;
}

