async function runTaskInlineWithRetries(
  env: Env,
  workspaceId: string,
  taskId: string,
  maxCycles = 8
): Promise<void> {
  for (let cycle = 0; cycle < maxCycles; cycle += 1) {
    try {
      await processWorkspaceTask(env, workspaceId, taskId);
    } catch {
      // Retry scheduling is inferred from persisted task status.
    }

